use std::rc::Rc;
use std::cell::RefCell;

fn main() {
    let shared = Rc::new(RefCell::new(42));
    let clone1 = Rc::clone(&shared);
    let clone2 = Rc::clone(&shared);

    {
        let mut guard1 = clone1.borrow_mut();
        *guard1 = 100;
    }

    {
        let mut guard2 = clone2.borrow_mut();
        *guard2 = 200;
    }

    let final_value = *shared.borrow();
    assert_eq!(final_value, 200);
    println!("success");
}
